        en: { name: 'Afrigonia', description: 'A small restaurant in central Puerto Natales where Patagonian lamb, guanaco and seafood are cooked with African spices, an unusual cuisine much loved by travellers.', tip: 'Book dinner in advance and order the curried lamb or ceviche of local fish after a day in the park.' },
        es: { name: 'Restaurante Afrigonia', description: 'Un pequeño restaurante del centro de Puerto Natales donde el cordero patagónico, el guanaco y los mariscos se cocinan con especias africanas, una cocina original muy querida por los viajeros.', tip: 'Reserva la cena con antelación y pide el cordero al curry o un ceviche de pescado local tras un día en el parque.' },
        de: { name: 'Restaurant Afrigonia', description: 'Ein kleines Restaurant im Zentrum von Puerto Natales, in dem patagonisches Lamm, Guanako und Meeresfrüchte mit afrikanischen Gewürzen zubereitet werden – eine ungewöhnliche, bei Reisenden sehr beliebte Küche.', tip: 'Reservier das Abendessen vorab und bestell nach einem Tag im Park Curry-Lamm oder Ceviche aus lokalem Fisch.' },
        fr: { name: 'Restaurant Afrigonia', description: 'Un petit restaurant du centre de Puerto Natales où l’agneau de Patagonie, le guanaco et les fruits de mer sont cuisinés aux épices africaines, une cuisine originale très appréciée des voyageurs.', tip: 'Réservez le dîner à l’avance et commandez l’agneau au curry ou un ceviche de poisson local après une journée dans le parc.' },
        it: { name: 'Ristorante Afrigonia', description: 'Un piccolo ristorante nel centro di Puerto Natales dove agnello patagonico, guanaco e frutti di mare sono cucinati con spezie africane, una cucina originale molto amata dai viaggiatori.', tip: 'Prenota la cena in anticipo e ordina l’agnello al curry o un ceviche di pesce locale dopo una giornata nel parco.' },
